  "firstMeeting.fallback": "คุณคือนักสำรวจที่ปลุกฉันขึ้นมาสินะ ฝากตัวด้วยนะ",
  "firstMeeting.rex": "ข้าคือราชินีแห่งการต่อสู้",
  "firstMeeting.torika": "กัปตันอยู่ข้างหลังหนูนะคะ ข้างหน้าหนูจะขวางไว้เองค่ะ!",
  "firstMeeting.spino": "…สปิโนค่ะ ที่ไหนก็ได้ที่ได้ยินเสียงน้ำ จะตามไปทุกที่เลยค่ะ",
  "firstMeeting.luka": "นักวิจัยเหรอ? ถ้าไม่ใช่เรื่องด่วน ขอนอนต่ออีกหน่อยนะ",
  "firstMeeting.dodo": "กัปตัน ดูนี่สิ! การค้นพบแห่งศตวรรษ!",
  "firstMeeting.tia": "นักวิจัย เห็นของแวววาวตรงนั้นไหมคะ? ฉันไปเก็บมาได้ไหม?",
  "firstMeeting.stella": "ยินดีที่ได้รู้จักค่ะ รุ่นพี่! เส้นทางลมวันนี้ฉันอ่านไว้หมดแล้วค่ะ",
  "firstMeeting.meron": "เอ่อ เมรอนค่ะ… อยากวาดให้ ช่วยให้ดูหน้าหน่อยได้ไหมคะ?",
  "firstMeeting.pachi": "เฮ้ หลบไป! ฉันกำลังเปิดทางให้บอส",
  "firstMeeting.maki": "ขอวินิจฉัยก่อนนะเมี้ยว ดูเป็นแบบนี้ แต่เป็นหมอนะเมี้ยว!",
  "firstMeeting.keris": "รุ่นพี่ หาหนังสืออยู่เหรอคะ? ฉันจะพาไปค่ะ",
  "firstMeeting.delopi": "แท่นแท๊น! นี่กุญแจของคุณค่ะ นักวิจัย",
  "firstMeeting.nodonia": "เจ็บเมื่อไหร่ก็บอกนะ เจ้าตัวน้อย ฉันจะรับไว้แทนเอง",
  "firstMeeting.ella": "ฉันจะยืนหยัดไว้ ด้านหลังปล่อยให้ฉันเอง",
  "firstMeeting.mette": "เวทีที่มีไว้เพื่อคุณคนเดียว เริ่มขึ้นแล้ว",
  "firstMeeting.deina": "เดย์เอง! กำแพงนี่ยังไม่มีอะไรเลยนี่? วาดตรงนี้ได้ไหม?",
  "firstMeeting.maddy": "แมดดี้ค่ะ นักวิจัย ที่นี่ร้อนหน่อยนะคะ เปิดระบบทำความเย็นแรงขึ้นได้ไหมคะ?",
  "firstMeeting.terisa": "ถ้ามีตรงไหนขาดก็บอกนะคะ… ฉันจะเย็บให้เองค่ะ ท่านนักวิจัย",
  "firstMeeting.parua": "ไกล… ไกลมาก! มองเห็นทุกอย่างเลย",
  "firstMeeting.shute": "บอกว่าไม่ใช่อันนั้นไง! ฟังคำสั่งฉัน เดี๋ยวแบกให้",
  "firstMeeting.morphe": "…ผู้ดูแล? มาพอดีเลย รอหน่อยนะ… จะเปิดจอให้",
  "firstMeeting.dian": "กัปตันฉันจะปกป้องเองค่ะ! …อ๊ะ คุโระ! ชิโระ! มานี่!",
