  "relic.spino.unlockRecord": "สปีนาทำหน้าที่ยามใต้น้ำของห้องวิจัย เธอค่อนข้างเงียบแต่ทำหน้าที่แม่นยำเสมอ เส้นทางลาดตระเวนและบันทึกตรวจประตูน้ำไม่มีช่องโหว่ ฉันเห็นเธอใช้เวลานานตกแต่งตู้ปลาเล็ก ๆ หลังเลิกเวร ซึ่งดูเหมือนเธอเชื่อว่าไม่มีใครรู้ ฉันแอบเช็ดคราบน้ำและทรายรอบ ๆ โดยไม่บอกใคร และดูเหมือนเธอยังคิดว่าไม่ถูกจับได้ วันรุ่งขึ้น บนโต๊ะของฉันมีเปลือกหอยรูปทรงสมบูรณ์ที่สุดวางอยู่ ขนมที่ชอบคือไทยากิ แต่ปฏิเสธไส้ถั่วแดงและคัสตาร์ด รับเฉพาะไทยากิไส้พิซซ่า พอได้มาก็กัดหัวก่อนทันที ท่าทางนั้นเป็นนักล่าริมแม่น้ำชัด ๆ",
