  "relic.luka.unlockRecord": "หลังฟื้นคืน ลูกาถูกสังเกตว่าเป็นนักวิ่งระยะสั้นที่รักบ้านและการพักผ่อนเหนือสิ่งอื่นใด ด้วยกล้ามเนื้อท่อนล่างที่แน่นสมกับนักวิ่ง เขาจึงเข้ากับเรลิกสายกินเนื้อตัวอื่นได้ดีโดยรวม แม้จะนอนเหยียดยาวพักอยู่บนโซฟาห้องวิจัย พอฉันเดินผ่านเขาก็ทักก่อนเสมอ นั่นเป็นนิสัยของเขา ระหว่างกินชีสเค้กของโปรด เขากังวลเบา ๆ ว่าถ้าอ้วนขึ้นการวิ่งอาจช้าลง แต่แล้วก็กัดอีกคำและหัวเราะว่าแค่ขยับให้เต็มที่ในการวิ่งเร็วรอบหน้าก็พอ",
