  "relic.stella.squadNote": "เจ้าหน้าที่สังเกตการณ์อายุน้อยที่สุดของดวงตาสัญญาณ เธออ่านเส้นทางลมล่วงหน้าเพื่อกำหนดจุดที่พันธมิตรจะบินขึ้น และเพราะยังเป็นมือใหม่จึงยังเรียกนักวิจัยว่ารุ่นพี่",
  "relic.stella.researcherTitle": "รุ่นพี่",
  "relic.stella.unlockRecord": "สเตลลาปีนขึ้นหอควบคุมและวัดทิศทางกับแรงลมใหม่หลายครั้งต่อวัน เธอสวมเสื้อคลุมวิจัยหลวมโพรกที่คลุมถึงหลังมือโดยพับแค่แขนเสื้อ และมีวิธีของเธอเองคือไม่ลบแม้แต่ตัวเลขที่ผิด แต่ปล่อยไว้ด้านในแขนเสื้ออย่างนั้น วันที่การคำนวณตรงกัน เธอส่งแค่รายงานทำเหมือนไม่มีอะไร แต่ปลายหงอนกลับตั้งชัน ตั้งแต่สัปดาห์แรกที่ถูกส่งมาประจำ เธอท่องขั้นตอนการสังเกตขั้นสูงทั้งหมดได้ ทำให้รุ่นพี่ของดวงตาสัญญาณลนลาน เมื่อเรลิกตัวน้อยที่ได้ยินเรื่องนี้มารอที่ทางเดินแล้วเดินตาม เธอบอกว่ารำคาญแต่ก็ยังเดินช้าลงให้ เธอยอมรับเองว่าสายตาชื่นชมเหล่านั้นหนักอยู่บ้าง ถ้าถามว่าเสื้อคลุมเคยเป็นของใคร เธอจะบอกว่าเป็นความลับแล้วเงียบ",
