  "relic.delopi.squadNote": "สมาชิกกู้ซากอายุน้อยที่สุดของเฟืองรัตติกาล แม้ในภารกิจแทรกซึมที่ต้องเงียบ เขาก็ไม่หยุดทำให้ของที่เก็บมาหายไปในมือแล้วกลับมาอีก รุ่นพี่จึงต้องกดหงอนของเขาลงทุกครั้ง",
  "relic.delopi.researcherTitle": "นักวิจัย",
  "relic.delopi.unlockRecord": "หลังฟื้นคืน เดโลปีถูกสังเกตว่าเป็นเด็กที่มือไวกว่าความคิด กุญแจที่หายไปจากกระเป๋าของนักวิจัยกลับมาพร้อมคำทักทายเสมอ และสีหน้าตอนคืนดูสนุกกว่าตอนหยิบไปมาก หงอนหลังคอจะกางกว้างเฉพาะตอนจะทำให้ตกใจ และดูเหมือนเขาไม่รู้ว่ามันเห็นชัดทุกอย่าง วันที่กลับจากภารกิจ เขาจะถือสำรับไพ่ไล่ตามเรลิกตัวอื่น เล่นมายากลเดิมซ้ำราวสิบครั้ง จนไม่มีใครหลงกลแล้วถึงค่อยเดินหงอยไปที่มุม",
