  "relic.dian.catalogSummary": "เรลิกจากตัวอย่างจ่าฝูง สูง 1.34 m หนัก 29 kg มีรูปร่างมนุษย์เล็กและเบากว่าเพื่อนรุ่นเดียวกัน หูหมาป่าไดร์ และประสาทสัมผัสไว",
  "relic.dian.squadNote": "หน่วยเฝ้าระวังของโจรน้อย เธอตรวจพื้นที่อันตรายข้างหน้าพร้อมคุโระกับชิโระ และยึดทางไว้จนกว่าสมาชิกคณะสำรวจตัวน้อยจะออกไปอย่างปลอดภัย",
  "relic.dian.researcherTitle": "กัปตัน",
  "relic.dian.unlockRecord": "เดียนคือพนักงานพาร์ตไทม์มือใหม่ซุ่มซ่ามที่เดินหลงเข้ามาในคาเฟ่หมา เวลาเสิร์ฟเธอพันกับคุโระและชิโระจนโต๊ะเละ แต่ทันทีที่แขกหรือลูกหมาตกใจ เธอจะก้าวไปขวางกลางก่อนใคร ที่ข้อมือเธอผูกกระดิ่งเล็ก ๆ ไว้ คุโระกับชิโระขยับตามเสียงนั้นเสียงเดียว ดังหนึ่งครั้งคือคุโระ สองครั้งคือชิโระ เธอถือว่าฉันเป็น \"หัวหน้า\" ของฝูงที่ต้องปกป้อง แต่ก็ยังเรียกฉันว่า \"กัปตัน\" ในภารกิจ เธอส่งหมาป่าสองตัวไปตรวจพื้นที่อันตรายก่อน และอยู่รั้งท้ายสุดจนกว่าสมาชิกคณะสำรวจตัวน้อยทุกคนจะกลับบ้าน",
