  "relic.kuro.fossilRecord": "หมาป่าไดร์ขนดำ หนึ่งในสองตัวที่ขุดพบข้างตัวอย่างจ่าฝูง ขาหน้ามีรอยยึดกล้ามเนื้อหนา ยืนยันนิสัยพุ่งเข้าชาร์จ",
  "relic.dimo.fossilRecord": "ไม่ใช่ตัวอย่างที่ฟื้นคืนจากฟอสซิล แต่เป็นโดรนควบคุมที่ติดอยู่กับเปลของมอร์เฟ ตัวเครื่องทั้งสองข้างติดพังผืดที่เลียนแบบพังผืดขาหน้าของตัวอย่างหมายเลข 206",
