  "relic.mosana.fossilRecord": "ลึกเข้าไปในอุโมงค์เหมืองหินปูน พบโครงกระดูกที่มีขากรรไกรขนาดใหญ่และกระดูกหางที่หักงอลงที่ปลาย กระดูกสันหลังปลายหางสึกเพียงด้านเดียวราวกับเคยพันสิ่งใดไว้แล้วลาก จึงสันนิษฐานว่ามันลากเหยื่อลงไปใต้น้ำ",
  "relic.mosana.catalogSummary": "ตัวอย่างโมซาซอรัสโตเต็มวัยที่ฟื้นคืนมาในรูปร่างมนุษย์สูง 1.62 ม. หนัก 49 กก. พร้อมหางฟันเลื่อยที่มีครีบรูปสมอ ชุดดำน้ำครบชุด และโดรนสำรวจหนึ่งเครื่อง",
  "relic.mosana.squadNote": "ผู้รับผิดชอบงานกู้ซากใต้ทะเลลึกของไนท์เกียร์ เธอดำลงไปในเขตที่จมน้ำก่อนเพื่อเปิดทาง และใช้เชือกเส้นเดียวลากซากและอุปกรณ์ที่สมาชิกนำกลับมาไม่ได้ขึ้นมา",
  "relic.mosana.researcherTitle": "นาย",
  "relic.mosana.unlockRecord": "หลังฟื้นคืน โมซานาใช้เวลาส่วนใหญ่อยู่ที่ก้นถังน้ำหรือในอุโมงค์กู้ซาก เธอแทบไม่ถอดหน้ากาก คำพูดจึงสั้นและขาดเป็นห้วง บางครั้งก็ตอบแทนด้วยการกะพริบไฟของโดรนสองครั้ง เมื่อสมาชิกคนอื่นถามว่า \"กลับมาแล้วเหรอ?\" เธอก็แค่พยักหน้า แต่รายชื่อซากที่กู้ขึ้นมานั้นเธอจดไว้ไม่ตกสักบรรทัดแล้วแปะไว้หน้าประตูห้องควบคุม วันที่กลับมาพร้อมเชือกที่ขาด เธอไม่บอกใครแล้วดำลงไปอีกครั้ง ในเสียงที่บันทึกไว้เหลือเพียงคำที่เธอพูดกับโดรนว่า \"อีกนิดเดียว\"",
