  "relic.ark.fossilRecord": "จากก้นหลุมทาร์พบกระดูกใบหน้าที่สั้นและสูง กับกระดูกขาหน้าที่ยาวผิดปกติ จับตัวแข็งเป็นก้อนเดียวกัน ระดับที่เอื้อมถึงเมื่อยืนขึ้นสูงกว่าที่คาดไว้ตอนขุดค้นมาก การวิจัยฟื้นฟูจึงเริ่มจากการวัดว่าเมื่อตัวนี้ยืนขึ้นแล้วเงาของมันทอดไปไกลเพียงใด",
