  "relic.yuti.fossilRecord": "บนแผ่นหินทัฟฟ์ที่แข็งตัวจากเถ้าภูเขาไฟ มีรอยประทับของขนนกที่ปกคลุมลำตัวหลงเหลืออยู่พร้อมกับกระดูก ร่างกายที่ใหญ่กว่าตัวอื่นในชั้นเดียวกันมากถูกพบพับอยู่ในแผ่นเดียว และการวิจัยฟื้นฟูเริ่มจากการวัดว่าขนนกเหล่านั้นห่อหุ้มลำตัวไปถึงตรงไหน",
  "relic.yuti.catalogSummary": "ตัวอย่างจากฟอสซิลยูทิแรนนัสวัยโตเต็มวัย รูปร่างแบบมนุษย์ที่คล่องแคล่วสูง 1.68 ม. หนัก 52 กก. ซึ่งยืนยันว่ามีเครื่องประดับขนนกพันรอบคอและแขน",
  "relic.yuti.squadNote": "ผู้แทรกซึมด้านข้างของเขี้ยวสัมบูรณ์ เธอลอดช่องว่างระหว่างเพื่อนที่ปะทะตรง ๆ ไปอย่างสายลมและจัดการศัตรูที่อ่อนแรง เรียกนักวิจัยว่า \"บอส\"",
  "relic.yuti.researcherTitle": "บอส",
  "relic.yuti.unlockRecord": "หลังการฟื้นคืนชีพ ยูทิลัดเลาะผ่านผู้คนจากปลายทางเดินไปอีกปลายโดยไม่ส่งเสียงดัง พบพฤติกรรมว่าเมื่อทุกคนมองไปข้างหน้า เธอก็มานั่งอยู่ข้างตัวตั้งแต่เมื่อไรไม่รู้ และเมื่อสบตากันก็เบนสายตาหนี ทำเป็นว่าไม่ใช่ฝีมือตัวเอง เธอเลียนแบบรุ่นพี่ที่โดดเด่นด้วยการใช้คำเรียกนักวิจัย แต่ก็เก้อเขินจนพูดไม่จบประโยคทุกครั้ง",
