  "relic.yuti.passive.desc": "เข้าสู่การต่อสู้ในสภาพล่องหน 4 วินาที อัตราคริติคอลและความเร็วโจมตีเพิ่มขึ้น เมื่อกำจัดศัตรู ความเร็วโจมตีและความเร็วเคลื่อนที่เพิ่มขึ้น 4 วินาที",
