  "keyword.intimidation.term": "ความข่มขวัญ",
  "keyword.intimidation.description": "เครื่องหมายที่ไม่สร้างความเสียหาย หนึ่งชั้นคงอยู่ 8 วินาที เมื่อครบ 3 ชั้นจะเกิด[[fear|ความหวาดกลัว]]เองและชั้นจะหายไป ศัตรูที่กำลังหวาดกลัวหรือมีภูมิคุ้มกันจะไม่สะสม",
  "keyword.meteor.term": "ดาวตก",
  "keyword.meteor.description": "ตกลงมาจากฟ้า สร้าง[[magical-damage|ความเสียหายเวท]]เท่ากับ 150% ของ[[ap|พลังเวท]]แก่ศัตรูทั้งหมดในวง",
  "keyword.fear.term": "ความหวาดกลัว",
  "keyword.fear.description": "เป็นเวลา 2 วินาที จะวิ่งหนีจากผู้ที่ทำให้หวาดกลัวและใช้[[basic-attack|การโจมตีปกติ]]ไม่ได้ แต่ยังใช้อัลติเมตได้ ระหว่างนั้น[[def|พลังป้องกัน]]และ[[res|พลังต้านทาน]]จะลดลง 50% หลังจบแล้ว 6 วินาทีจะมีภูมิคุ้มกันต่อความข่มขวัญและความหวาดกลัวใหม่",
  "firstMeeting.ark": "มุฮาฮาฮา! เห็นไหม นายท่าน? ทุกคนเบียดชิดผนังหมดเลย ...เดี๋ยวนะ เมื่อกี้น่ากลัวใช่ไหม?",
  "firstMeeting.yuti": "บอส ตรงนี้ว่างใช่ไหมคะ? ขออยู่ข้าง ๆ ได้ไหม?",
  "relic.teku.name": "เทคุ",
  "relic.teku.projectName": "ALL-NIGHT BREW",
  "relic.teku.origin": "จิแกนโตพิเทคัส",
  "relic.teku.excavationSite": "ชั้นตะกอนถ้ำหินปูนในฉงจั่ว เขตปกครองตนเองกว่างซีจ้วง ประเทศจีน",
  "relic.teku.fossilRecord": "พบฟันกรามหลายสิบซี่และชิ้นส่วนขากรรไกรเรียงเป็นแถวเดียวในชั้นดินเหนียวบนพื้นถ้ำ ฟันกรามแบนราบ พื้นผิวที่สึกเรียบมันเหมือนกระจก บอกได้เพียงว่าเป็นปากที่เคี้ยวหญ้าเหนียวและผลไม้ไม่หยุด เป็นชนิดเดียวกับที่ร้านขายยาในท้องถิ่นขายมาแต่โบราณในชื่อ ‘ฟันมังกร’ การวิจัยฟื้นฟูจึงเริ่มจากการเทียบกับบันทึกตัวยาที่บดเป็นผง",
  "relic.teku.catalogSummary": "ตัวอย่างจากฟอสซิลจิแกนโตพิเทคัสวัยโต รูปร่างมนุษย์สูง 1.50 ม. หนัก 47 กก. ยืนยันว่ามีรอยคล้ำใต้ตาและมือที่กำถ้วยใบใหญ่",
  "relic.teku.squadNote": "คนเดียวในโจรน้อยที่ใจเย็น เธออยู่มุมหนึ่งของทีมสำรวจที่วุ่นวาย แจกเครื่องดื่มให้บรรยากาศสงบลง และเรียกนักวิจัยว่า “กัปตัน”",
  "relic.teku.researcherTitle": "กัปตัน",
  "relic.teku.unlockRecord": "หลังฟื้นฟู เทคุนั่งริมหน้าต่างห้องดูแล ใช้สองมือโอบถ้วยเครื่องดื่มมัทฉะเข้มข้น จิบทีละอึกอย่างช้ามาก ไม่เคยรีบร้อน พอเห็นก้นถ้วยก็เงียบ ๆ ยื่นมือออกมาแล้วพูดเพียงคำเดียวว่า \"เติม\" อดนอนมาทั้งคืนเสียงก็ไม่เปลี่ยนไปเลย คนที่อยู่ข้าง ๆ เคยพนันกันว่าที่เธอไม่ง่วงนั้นเป็นเพราะคาเฟอีนหรือมัทฉะ แม้อยู่ท่ามกลางเด็ก ๆ ที่วิ่งเล่นส่งเสียงดัง เธอก็ดื่มจนหมดถ้วยด้วยจังหวะเดิม และถ้ามีใครโวยวาย เธอจะยื่นอีกถ้วยให้โดยไม่พูดอะไรสักคำ",
